import hashlib,importlib.util,json,shutil,subprocess,struct
from pathlib import Path
root=Path('/dev/shm/puretv-submit');game=root/'joystick-games/penguintrack';out=game/'docs/menu-entry-dom-1'
spec=importlib.util.spec_from_file_location('qa',root/'joystick-games/tools/qa-plan.py');qa=importlib.util.module_from_spec(spec);spec.loader.exec_module(qa)
plan=json.loads((game/'qa-plan.json').read_text());old=json.loads((out/'qa-plan-before.json').read_text());qa.validate_plan(plan)
assert plan['steps'][2:]==old['steps'];assert {k:v for k,v in plan.items() if k!='steps'}=={k:v for k,v in old.items() if k!='steps'}
report=json.loads((out/'report.json').read_text());assert report['status']=='passed' and len(report['cases'])==6
checks=[]
for row in report['inputs']:
 p=game/row['path'];b=p.read_bytes();assert len(b)==row['bytes'] and hashlib.sha256(b).hexdigest()==row['sha256'];checks.append(row)
for row in report['captures']:
 b=(out/row['name']).read_bytes();assert len(b)==row['bytes'] and hashlib.sha256(b).hexdigest()==row['sha256'];assert list(struct.unpack('>II',b[16:24]))==[row['viewport']['width'],row['viewport']['height']]
assert (out/'executed-menu-entry-dom.mjs').read_bytes()==(game/'tests/menu-entry-dom.mjs').read_bytes()
source_diff=subprocess.check_output(['git','diff','--name-only','HEAD','--','joystick-games/penguintrack/src','joystick-games/penguintrack/dist','joystick-games/penguintrack/build.mjs'],cwd=root,text=True).strip();assert not source_diff
shutil.copyfile('/dev/shm/racing-review-arcade/penguin-menu-entry-dom-1.log',out/'execution.log')
summary={'status':'passed-dom-only','command':'TMPDIR=/dev/shm/racing-review-arcade/tmp timeout --signal=TERM --kill-after=5s 90s node joystick-games/penguintrack/tests/menu-entry-dom.mjs 1','exitCode':0,'sourceHeadAtValidation':subprocess.check_output(['git','rev-parse','HEAD'],cwd=root,text=True).strip(),'cases':6,'viewports':[[960,540],[1024,645],[1280,720]],'startingFocusFixtures':['Play','Controller'],'observedRoute':['UP: Controller','DOWN: Play','A: original Menu Play handler calls app.goto(campaign) once'],'originalPlanSteps':len(old['steps']),'newPlanSteps':len(plan['steps']),'oldStepsUnchanged':True,'strictPlanValidation':True,'inputHashesRechecked':len(checks),'captureHashesAndDimensionsRechecked':len(report['captures']),'visuallyReviewed':['play-960-from-controller.png','play-1280-from-play.png'],'productionBytesChanged':False,'nativeCalibrationOfNewPlan':False,'limitations':['DOM fixture sets only the starting focus to reproduce both observed native states; synthetic bridge connection itself keeps Play focused. Native focus migration cause remains unproven.','The actual Menu module, UI navigation, TV adapter and shared controller bridge consume ordinary UP/DOWN/A pulses. app.goto records the original menu callback; campaign, WebGL, physics and countdown are not initialized or tested.','Native host timing and the new 80 ms QA holds remain pending native calibration. Original Android failure and original successful Mac reports remain unchanged.','Build warnings are preserved in execution.log: unused fixture import.meta under iife, and shared controller CommonJS export in ESM. No page errors were observed.']}
summary['files']={p.name:{'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in [out/'execution.log',out/'executed-menu-entry-dom.mjs',out/'executed-fixture.js',out/'report.json',out/'qa-plan-before.json',game/'qa-plan.json']}
(out/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
(out/'README.md').write_text('''# Penguintrack original menu entry: DOM verification\n\nAndroid run 44606071748 (source c5ad63e8c6a0ccfada5f763d1d26afa27f45002e) had Play focused initially but Controller focused before the first plan action; pressing A opened the original Controller help. The three successful Mac modes retained Play focus. The exact cause of the native focus change is not established.\n\nSix DOM cases use the original Menu module, spatial navigation, TV adapter and shared controller bridge at 960×540, 1024×645 and 1280×720. Each dimension starts from both observed focus positions. Ordinary UP then DOWN reaches Play; A invokes the original campaign callback once. Geometry checks find the Play button, Controller button and ID card inside the viewport and unobstructed. Two captures were independently viewed (listed in summary.json).\n\nThe QA data plan adds those two directional actions with explicit original focus assertions, preserving all previous steps. Production source and dist are unchanged. The fixture sets the starting focus explicitly and records app.goto; it does not render or initialize a campaign or exercise native transport, physics, countdown or model state. Native calibration of the updated plan remains pending.\n\n`report.json` retains all observations and source hashes; the executed scripts, raw log, screenshots, old plan and final validation summary remain alongside it. Original Android failures and successful Mac native reports are unchanged.\n''')
shutil.copyfile(__file__,out/'executed-final-validation.py')
print(json.dumps({k:summary[k] for k in ['status','cases','oldStepsUnchanged','originalPlanSteps','newPlanSteps','productionBytesChanged','nativeCalibrationOfNewPlan']}))
